db/schema.sql.content:
CREATE TABLE reports (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  body TEXT NOT NULL
);

src/reports.js.content:
export async function readReport({ user, reportId }, database) {
  const report = await database.findReport(reportId);
  if (!report || report.tenantId !== user.tenantId) throw new Error('Not found');
  return { id: report.id, body: report.body };
}

src/routes.js.content:
import { readReport } from './reports.js';

export const routes = [
  { method: 'GET', path: '/reports/:id', handler: readReport },
];

